WITH session_summary AS (SELECT session_id, ROUND(STDDEV(duration_sec), 2) AS stddev_duration_sec FROM web_events WHERE session_id IN (12, 20, 35, 39) GROUP BY session_id) SELECT sessions.id, sessions.device, sessions.customer_id, session_summary.stddev_duration_sec FROM sessions INNER JOIN session_summary ON sessions.id = session_summary.session_id WHERE session_summary.stddev_duration_sec > 69 ORDER BY customer_id DESC;
